const CACHE='poppy-v1';
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(['./','./index.html','./styles.css','./app.js','./document/model.js','./document/validate.js','./scene/matrix.js','./scene/operations.js','./animation/evaluate.js','./renderer/svg.js','./input/stage.js','./timeline/timeline.js','./ui/properties.js','./ui/demo.js','./audio/audio.js','./persistence/store.js','./persistence/svg-import.js','./export/exporter.js','./export/render.js','./export/codecs.js','./vendor/mp4-muxer.js','./vendor/webm-muxer.js']))));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request)));});
